# ---------------------------------------------------------------------------
# Banco de dados (SQLite)
# ---------------------------------------------------------------------------

SCHEMA_SQL = """
CREATE TABLE IF NOT EXISTS products (
  id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
  code TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  category TEXT NOT NULL,
  unit TEXT NOT NULL,
  price_cents INTEGER NOT NULL,
  minimum_quantity REAL NOT NULL DEFAULT 0,
  description TEXT NOT NULL DEFAULT '',
  active INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS settings (
  key TEXT PRIMARY KEY NOT NULL,
  value TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS categories (
  id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
  name TEXT NOT NULL UNIQUE,
  created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS quotes (
  id TEXT PRIMARY KEY NOT NULL,
  quote_number TEXT NOT NULL UNIQUE,
  customer_name TEXT NOT NULL,
  customer_phone TEXT NOT NULL DEFAULT '',
  event_date TEXT,
  event_time TEXT,
  valid_until TEXT NOT NULL,
  notes TEXT NOT NULL DEFAULT '',
  subtotal_cents INTEGER NOT NULL,
  deposit_percent REAL NOT NULL,
  created_at TEXT NOT NULL,
  approved INTEGER NOT NULL DEFAULT 0,
  discount_percent REAL NOT NULL DEFAULT 0,
  final_cents INTEGER NOT NULL DEFAULT 0,
  deposit_paid_cents INTEGER
);
CREATE TABLE IF NOT EXISTS quote_items (
  id TEXT PRIMARY KEY NOT NULL,
  quote_id TEXT NOT NULL,
  product_id INTEGER,
  product_name TEXT NOT NULL,
  unit TEXT NOT NULL,
  quantity REAL NOT NULL,
  unit_price_cents INTEGER NOT NULL,
  total_cents INTEGER NOT NULL,
  FOREIGN KEY (quote_id) REFERENCES quotes(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_products_active_category ON products (active, category);
CREATE INDEX IF NOT EXISTS idx_quote_items_quote_id ON quote_items (quote_id);
CREATE INDEX IF NOT EXISTS idx_quotes_created_at ON quotes (created_at);
"""


def now_iso():
    return datetime.now(timezone.utc).isoformat()


def new_id():
    return uuid.uuid4().hex


def get_connection():
    DATABASE_PATH.parent.mkdir(parents=True, exist_ok=True)
    conn = sqlite3.connect(str(DATABASE_PATH), timeout=5)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA journal_mode = WAL")
    conn.execute("PRAGMA foreign_keys = ON")
    conn.execute("PRAGMA busy_timeout = 5000")
    return conn


def init_schema(conn):
    conn.executescript(SCHEMA_SQL)
    conn.commit()
    _run_migrations(conn)


def _run_migrations(conn):
    """Ajustes de esquema para bancos criados por versões anteriores deste
    arquivo, já que CREATE TABLE IF NOT EXISTS não adiciona colunas novas em
    uma tabela que já existe."""
    columns = {row["name"] for row in conn.execute("PRAGMA table_info(quotes)")}
    if "approved" not in columns:
        conn.execute("ALTER TABLE quotes ADD COLUMN approved INTEGER NOT NULL DEFAULT 0")
        conn.commit()
    if "discount_percent" not in columns:
        conn.execute("ALTER TABLE quotes ADD COLUMN discount_percent REAL NOT NULL DEFAULT 0")
        conn.commit()
    if "final_cents" not in columns:
        conn.execute("ALTER TABLE quotes ADD COLUMN final_cents INTEGER NOT NULL DEFAULT 0")
        # pedidos criados antes deste campo existir nunca tinham desconto,
        # então o valor final é igual ao subtotal.
        conn.execute("UPDATE quotes SET final_cents = subtotal_cents WHERE final_cents = 0")
        conn.commit()
    if "deposit_paid_cents" not in columns:
        conn.execute("ALTER TABLE quotes ADD COLUMN deposit_paid_cents INTEGER")
        conn.commit()
    if "event_time" not in columns:
        conn.execute("ALTER TABLE quotes ADD COLUMN event_time TEXT")
        conn.commit()


def ensure_seeded(conn):
    product_total = conn.execute("SELECT COUNT(*) AS total FROM products").fetchone()["total"]
    if not product_total:
        stamp = now_iso()
        conn.executemany(
            """
            INSERT OR IGNORE INTO products
              (code, name, category, unit, price_cents, minimum_quantity, description, active, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, 1, ?, ?)
            """,
            [
                (code, name, category, unit, price_cents, minimum_quantity, description, stamp, stamp)
                for (code, name, category, unit, price_cents, minimum_quantity, description) in INITIAL_CATALOG
            ],
        )

    setting_total = conn.execute("SELECT COUNT(*) AS total FROM settings").fetchone()["total"]
    if not setting_total:
        conn.executemany(
            "INSERT OR IGNORE INTO settings (key, value) VALUES (?, ?)",
            list(DEFAULT_SETTINGS.items()),
        )

    category_total = conn.execute("SELECT COUNT(*) AS total FROM categories").fetchone()["total"]
    if not category_total:
        stamp = now_iso()
        seen = []
        for row in INITIAL_CATALOG:
            category = row[2]
            if category not in seen:
                seen.append(category)
        conn.executemany(
            "INSERT OR IGNORE INTO categories (name, created_at) VALUES (?, ?)",
            [(name, stamp) for name in seen],
        )

    conn.commit()


def with_db(fn):
    """Abre uma conexão, garante o schema/seed, executa fn(conn) sob a trava
    global de escrita e sempre fecha a conexão ao final."""
    with DB_LOCK:
        conn = get_connection()
        try:
            init_schema(conn)
            ensure_seeded(conn)
            return fn(conn)
        finally:
            conn.close()


# ---------------------------------------------------------------------------
# Lógica da API (equivalente a GET/POST /api/data do sistema anterior)
# ---------------------------------------------------------------------------

class ApiError(Exception):
    def __init__(self, message, status=400):
        super().__init__(message)
        self.message = message
        self.status = status


def row_to_product(row):
    return {
        "id": row["id"],
        "code": row["code"],
        "name": row["name"],
        "category": row["category"],
        "unit": row["unit"],
        "priceCents": row["price_cents"],
        "minimumQuantity": row["minimum_quantity"],
        "description": row["description"] or "",
        "active": bool(row["active"]),
    }


def row_to_quote_item(row):
    return {
        "id": row["id"],
        "productId": row["product_id"],
        "productName": row["product_name"],
        "unit": row["unit"],
        "quantity": row["quantity"],
        "unitPriceCents": row["unit_price_cents"],
        "totalCents": row["total_cents"],
    }


def handle_get_data(conn):
    product_rows = conn.execute(
        "SELECT * FROM products ORDER BY active DESC, category, name"
    ).fetchall()
    setting_rows = conn.execute("SELECT key, value FROM settings ORDER BY key").fetchall()
    quote_rows = conn.execute(
        "SELECT * FROM quotes ORDER BY created_at DESC LIMIT 100"
    ).fetchall()
    item_rows = conn.execute(
        "SELECT * FROM quote_items ORDER BY quote_id, product_name"
    ).fetchall()

    category_rows = conn.execute(
        "SELECT id, name FROM categories ORDER BY name"
    ).fetchall()

    settings = {row["key"]: row["value"] for row in setting_rows}
    items_by_quote = {}
    for item in item_rows:
        items_by_quote.setdefault(item["quote_id"], []).append(row_to_quote_item(item))

    quotes = []
    for row in quote_rows:
        quotes.append({
            "id": row["id"],
            "quoteNumber": row["quote_number"],
            "customerName": row["customer_name"],
            "customerPhone": row["customer_phone"] or "",
            "eventDate": row["event_date"],
            "eventTime": row["event_time"],
            "validUntil": row["valid_until"],
            "notes": row["notes"] or "",
            "subtotalCents": row["subtotal_cents"],
            "depositPercent": row["deposit_percent"],
            "createdAt": row["created_at"],
            "approved": bool(row["approved"]),
            "discountPercent": row["discount_percent"],
            "finalCents": row["final_cents"],
            "depositPaidCents": row["deposit_paid_cents"],
            "items": items_by_quote.get(row["id"], []),
        })

    return {
        "products": [row_to_product(row) for row in product_rows],
        "settings": settings,
        "quotes": quotes,
        "categories": [{"id": row["id"], "name": row["name"]} for row in category_rows],
    }


def action_save_settings(conn, body):
    settings = body.get("settings") or {}
    if "access_pin" in settings:
        pin = str(settings.get("access_pin") or "").strip()
        if not pin.isdigit() or not (4 <= len(pin) <= 6):
            raise ApiError("O código de acesso deve ter de 4 a 6 dígitos numéricos.", 400)
    conn.executemany(
        """
        INSERT INTO settings (key, value) VALUES (?, ?)
        ON CONFLICT(key) DO UPDATE SET value = excluded.value
        """,
        [(str(key), str(value)) for key, value in settings.items()],
    )
    conn.commit()
    return {"ok": True}


def action_save_product(conn, body):
    product = body.get("product") or {}
    name = str(product.get("name") or "").strip()
    category = str(product.get("category") or "").strip()
    price_cents = product.get("priceCents")
    if not name or not category or not price_cents:
        raise ApiError("Preencha nome, categoria e preço.", 400)

    stamp = now_iso()
    product_id = product.get("id")
    unit = product.get("unit") or "kg"
    minimum_quantity = float(product.get("minimumQuantity") or 0)
    description = product.get("description") or ""
    active = 0 if product.get("active") is False else 1

    if product_id:
        conn.execute(
            """
            UPDATE products SET code = ?, name = ?, category = ?, unit = ?, price_cents = ?,
              minimum_quantity = ?, description = ?, active = ?, updated_at = ? WHERE id = ?
            """,
            (
                product.get("code") or "",
                name,
                category,
                unit,
                round(float(price_cents)),
                minimum_quantity,
                description,
                active,
                stamp,
                int(product_id),
            ),
        )
    else:
        code = product.get("code") or f"NOVO-{int(time.time() * 1000)}"
        conn.execute(
            """
            INSERT INTO products
              (code, name, category, unit, price_cents, minimum_quantity, description, active, created_at, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, 1, ?, ?)
            """,
            (
                code,
                name,
                category,
                unit,
                round(float(price_cents)),
                minimum_quantity,
                description,
                stamp,
                stamp,
            ),
        )
    # garante que a categoria escolhida exista na lista de categorias
    conn.execute(
        "INSERT OR IGNORE INTO categories (name, created_at) VALUES (?, ?)",
        (category, stamp),
    )
    conn.commit()
    return {"ok": True}


def action_toggle_product(conn, body):
    conn.execute(
        "UPDATE products SET active = ?, updated_at = ? WHERE id = ?",
        (1 if body.get("active") else 0, now_iso(), int(body.get("id"))),
    )
    conn.commit()
    return {"ok": True}


def action_save_category(conn, body):
    category = body.get("category") or {}
    name = str(category.get("name") or "").strip()
    category_id = category.get("id")
    if not name:
        raise ApiError("Informe o nome da categoria.", 400)

    if category_id:
        existing = conn.execute(
            "SELECT name FROM categories WHERE id = ?", (int(category_id),)
        ).fetchone()
        if not existing:
            raise ApiError("Categoria não encontrada.", 404)
        old_name = existing["name"]
        conn.execute(
            "UPDATE categories SET name = ? WHERE id = ?", (name, int(category_id))
        )
        if old_name != name:
            # renomear a categoria atualiza os produtos que a usavam
            conn.execute(
                "UPDATE products SET category = ?, updated_at = ? WHERE category = ?",
                (name, now_iso(), old_name),
            )
    else:
        conn.execute(
            "INSERT INTO categories (name, created_at) VALUES (?, ?)",
            (name, now_iso()),
        )
    conn.commit()
    return {"ok": True}


def action_delete_category(conn, body):
    category_id = body.get("id")
    if not category_id:
        raise ApiError("Categoria inválida.", 400)
    row = conn.execute(
        "SELECT name FROM categories WHERE id = ?", (int(category_id),)
    ).fetchone()
    if not row:
        raise ApiError("Categoria não encontrada.", 404)
    in_use = conn.execute(
        "SELECT COUNT(*) AS total FROM products WHERE category = ?", (row["name"],)
    ).fetchone()["total"]
    if in_use:
        raise ApiError(
            f"Existem {in_use} produto(s) usando esta categoria. Mova-os para outra categoria antes de excluir.",
            400,
        )
    conn.execute("DELETE FROM categories WHERE id = ?", (int(category_id),))
    conn.commit()
    return {"ok": True}


def action_save_quote(conn, body):
    quote = body.get("quote") or {}
    customer_name = str(quote.get("customerName") or "").strip()
    items = quote.get("items") or []
    if not customer_name or not items:
        raise ApiError("Informe o cliente e adicione pelo menos um item.", 400)

    subtotal_cents = round(float(quote.get("subtotalCents") or 0))
    deposit_paid = quote.get("depositPaidCents")
    conn.execute(
        """
        INSERT INTO quotes
          (id, quote_number, customer_name, customer_phone, event_date, event_time, valid_until, notes,
           subtotal_cents, deposit_percent, created_at, discount_percent, final_cents, deposit_paid_cents)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            quote.get("id") or new_id(),
            quote.get("quoteNumber") or "",
            customer_name,
            quote.get("customerPhone") or "",
            quote.get("eventDate") or None,
            quote.get("eventTime") or None,
            quote.get("validUntil") or "",
            quote.get("notes") or "",
            subtotal_cents,
            float(quote.get("depositPercent") or 0),
            quote.get("createdAt") or now_iso(),
            float(quote.get("discountPercent") or 0),
            round(float(quote.get("finalCents"))) if quote.get("finalCents") is not None else subtotal_cents,
            round(float(deposit_paid)) if deposit_paid is not None else None,
        ),
    )
    for item in items:
        conn.execute(
            """
            INSERT INTO quote_items
              (id, quote_id, product_id, product_name, unit, quantity, unit_price_cents, total_cents)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                item.get("id") or new_id(),
                quote.get("id"),
                item.get("productId"),
                item.get("productName") or "",
                item.get("unit") or "",
                float(item.get("quantity") or 0),
                round(float(item.get("unitPriceCents") or 0)),
                round(float(item.get("totalCents") or 0)),
            ),
        )
    conn.commit()
    return {"ok": True, "quote": quote}


def action_update_quote(conn, body):
    quote = body.get("quote") or {}
    quote_id = quote.get("id")
    customer_name = str(quote.get("customerName") or "").strip()
    items = quote.get("items") or []
    if not quote_id:
        raise ApiError("Orçamento inválido.", 400)
    if not customer_name or not items:
        raise ApiError("Informe o cliente e adicione pelo menos um item.", 400)

    existing = conn.execute("SELECT id FROM quotes WHERE id = ?", (quote_id,)).fetchone()
    if not existing:
        raise ApiError("Orçamento não encontrado.", 404)

    subtotal_cents = round(float(quote.get("subtotalCents") or 0))
    deposit_paid = quote.get("depositPaidCents")
    conn.execute(
        """
        UPDATE quotes SET customer_name = ?, customer_phone = ?, event_date = ?, event_time = ?,
          valid_until = ?, notes = ?, subtotal_cents = ?, deposit_percent = ?, discount_percent = ?, final_cents = ?,
          deposit_paid_cents = ? WHERE id = ?
        """,
        (
            customer_name,
            quote.get("customerPhone") or "",
            quote.get("eventDate") or None,
            quote.get("eventTime") or None,
            quote.get("validUntil") or "",
            quote.get("notes") or "",
            subtotal_cents,
            float(quote.get("depositPercent") or 0),
            float(quote.get("discountPercent") or 0),
            round(float(quote.get("finalCents"))) if quote.get("finalCents") is not None else subtotal_cents,
            round(float(deposit_paid)) if deposit_paid is not None else None,
            quote_id,
        ),
    )
    # Substitui os itens por completo: mais simples e seguro do que tentar
    # calcular um diff entre a lista antiga e a nova.
    conn.execute("DELETE FROM quote_items WHERE quote_id = ?", (quote_id,))
    for item in items:
        conn.execute(
            """
            INSERT INTO quote_items
              (id, quote_id, product_id, product_name, unit, quantity, unit_price_cents, total_cents)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                item.get("id") or new_id(),
                quote_id,
                item.get("productId"),
                item.get("productName") or "",
                item.get("unit") or "",
                float(item.get("quantity") or 0),
                round(float(item.get("unitPriceCents") or 0)),
                round(float(item.get("totalCents") or 0)),
            ),
        )
    conn.commit()
    return {"ok": True, "quote": quote}


def action_delete_quote(conn, body):
    quote_id = body.get("id")
    if not quote_id:
        raise ApiError("Orçamento inválido.", 400)
    # ON DELETE CASCADE (com foreign_keys=ON) já remove os itens junto.
    cursor = conn.execute("DELETE FROM quotes WHERE id = ?", (str(quote_id),))
    conn.commit()
    if cursor.rowcount == 0:
        raise ApiError("Orçamento não encontrado.", 404)
    return {"ok": True}


def action_toggle_quote_approval(conn, body):
    quote_id = body.get("id")
    if not quote_id:
        raise ApiError("Orçamento inválido.", 400)
    cursor = conn.execute(
        "UPDATE quotes SET approved = ? WHERE id = ?",
        (1 if body.get("approved") else 0, str(quote_id)),
    )
    conn.commit()
    if cursor.rowcount == 0:
        raise ApiError("Orçamento não encontrado.", 404)
    return {"ok": True}


ACTIONS = {
    "saveSettings": action_save_settings,
    "saveProduct": action_save_product,
    "toggleProduct": action_toggle_product,
    "saveCategory": action_save_category,
    "deleteCategory": action_delete_category,
    "saveQuote": action_save_quote,
    "updateQuote": action_update_quote,
    "deleteQuote": action_delete_quote,
    "toggleQuoteApproval": action_toggle_quote_approval,
}


def handle_post_action(conn, body):
    action = body.get("action")
    handler = ACTIONS.get(action)
    if not handler:
        raise ApiError("Ação não reconhecida.", 400)
    try:
        return handler(conn, body)
    except ApiError:
        raise
    except sqlite3.IntegrityError as error:
        conn.rollback()
        if "UNIQUE" in str(error):
            raise ApiError("Já existe um registro com este nome ou código.", 500)
        raise ApiError("Não foi possível salvar agora.", 500)
    except Exception as error:  # noqa: BLE001 - queremos responder 500 amigável
        conn.rollback()
        print(f"Falha ao salvar dados: {error}", file=sys.stderr)
        raise ApiError("Não foi possível salvar agora.", 500)


