def _pdf_char_width(ch, bold):
    table = _HELVETICA_BOLD_WIDTHS if bold else _HELVETICA_WIDTHS
    if ch in table:
        return table[ch]
    base = _ACCENT_BASE.get(ch)
    if base and base in table:
        return table[base]
    return 556


def _pdf_text_width(s, size, bold=False):
    return sum(_pdf_char_width(ch, bold) for ch in s) * size / 1000.0


def _pdf_wrap_text(s, size, max_width, bold=False):
    if not s:
        return []
    lines = []
    for paragraph in s.split("\n"):
        words = paragraph.split(" ")
        current = ""
        for word in words:
            candidate = (current + " " + word).strip() if current else word
            if _pdf_text_width(candidate, size, bold) <= max_width or not current:
                current = candidate
            else:
                lines.append(current)
                current = word
        lines.append(current)
    return lines


def _pdf_escape(s):
    return s.replace("\\", "\\\\").replace("(", "\\(").replace(")", "\\)")


def _pdf_encode_text(s):
    return s.encode("cp1252", errors="replace").decode("latin1")


# ---------------------------------------------------------------------
# Decodificador de PNG próprio (só para embutir a logo no PDF — nada de
# bibliotecas de imagem, só zlib da biblioteca padrão). Suporta o caso
# usado pela logo: 8 bits por canal, RGBA, sem entrelaçamento.
# ---------------------------------------------------------------------

def _png_paeth(a, b, c):
    p = a + b - c
    pa = abs(p - a)
    pb = abs(p - b)
    pc = abs(p - c)
    if pa <= pb and pa <= pc:
        return a
    if pb <= pc:
        return b
    return c


def _png_decode_rgba8(png_bytes):
    """Decodifica um PNG de 8 bits/RGBA/sem entrelaçamento e devolve
    (largura, altura, bytes RGBA intercalados)."""
    if png_bytes[:8] != b"\x89PNG\r\n\x1a\n":
        raise ValueError("arquivo não é um PNG válido")

    pos = 8
    idat = bytearray()
    width = height = None
    while pos < len(png_bytes):
        length = int.from_bytes(png_bytes[pos:pos + 4], "big")
        ctype = png_bytes[pos + 4:pos + 8].decode("ascii")
        chunk = png_bytes[pos + 8:pos + 8 + length]
        if ctype == "IHDR":
            width, height, bitdepth, colortype, comp, filt, interlace = struct.unpack(">IIBBBBB", chunk)
            if bitdepth != 8 or colortype != 6 or interlace != 0:
                raise ValueError("só decodifico PNG de 8 bits, RGBA, sem entrelaçamento")
        elif ctype == "IDAT":
            idat += chunk
        elif ctype == "IEND":
            break
        pos += 8 + length + 4

    raw = zlib.decompress(bytes(idat))
    bpp = 4
    rowbytes = width * bpp
    recon = bytearray(rowbytes * height)
    prev_row_start = None
    src_pos = 0
    for y in range(height):
        filter_type = raw[src_pos]
        src_pos += 1
        row_start = y * rowbytes
        for i in range(rowbytes):
            x = raw[src_pos + i]
            a = recon[row_start + i - bpp] if i >= bpp else 0
            if prev_row_start is not None:
                b = recon[prev_row_start + i]
                c = recon[prev_row_start + i - bpp] if i >= bpp else 0
            else:
                b = c = 0
            if filter_type == 0:
                val = x
            elif filter_type == 1:
                val = x + a
            elif filter_type == 2:
                val = x + b
            elif filter_type == 3:
                val = x + (a + b) // 2
            elif filter_type == 4:
                val = x + _png_paeth(a, b, c)
            else:
                raise ValueError(f"tipo de filtro PNG desconhecido: {filter_type}")
            recon[row_start + i] = val & 0xFF
        src_pos += rowbytes
        prev_row_start = row_start
    return width, height, bytes(recon)


_LOGO_IMAGE_CACHE = None


def _get_logo_image_data():
    """Decodifica a logo (base64 -> PNG -> RGBA) uma única vez e guarda em
    cache: separada em plano RGB e plano Alfa (para /SMask), já comprimidos
    com zlib, prontos para entrar direto no PDF. Se por algum motivo a
    decodificação falhar, devolve None e o PDF cai para um cabeçalho só de
    texto (ver _QuoteDocumentPdf._header)."""
    global _LOGO_IMAGE_CACHE
    if _LOGO_IMAGE_CACHE is None:
        try:
            png_bytes = base64.b64decode(LOGO_BASE64)
            width, height, rgba = _png_decode_rgba8(png_bytes)
            pixel_count = width * height
            rgb = bytearray(pixel_count * 3)
            alpha = bytearray(pixel_count)
            for i in range(pixel_count):
                o = i * 4
                rgb[i * 3] = rgba[o]
                rgb[i * 3 + 1] = rgba[o + 1]
                rgb[i * 3 + 2] = rgba[o + 2]
                alpha[i] = rgba[o + 3]
            _LOGO_IMAGE_CACHE = {
                "width": width,
                "height": height,
                "rgb": zlib.compress(bytes(rgb), 9),
                "alpha": zlib.compress(bytes(alpha), 9),
            }
        except Exception as error:  # noqa: BLE001
            print(f"Falha ao preparar a logo para o PDF: {error}", file=sys.stderr)
            _LOGO_IMAGE_CACHE = False
    return _LOGO_IMAGE_CACHE or None


class _PdfPage:
    def __init__(self, width=595.28, height=841.89):
        self.width = width
        self.height = height
        self.ops = []

    def set_fill(self, r, g, b):
        self.ops.append(f"{r:.3f} {g:.3f} {b:.3f} rg")

    def set_stroke(self, r, g, b):
        self.ops.append(f"{r:.3f} {g:.3f} {b:.3f} RG")

    def rect(self, x, y, w, h, fill=False, stroke=False, line_width=1):
        self.ops.append(f"{line_width:.2f} w")
        self.ops.append(f"{x:.2f} {y:.2f} {w:.2f} {h:.2f} re")
        if fill and stroke:
            self.ops.append("B")
        elif fill:
            self.ops.append("f")
        elif stroke:
            self.ops.append("S")

    def line(self, x1, y1, x2, y2, line_width=1):
        self.ops.append(f"{line_width:.2f} w")
        self.ops.append(f"{x1:.2f} {y1:.2f} m {x2:.2f} {y2:.2f} l S")

    def text(self, x, y, s, size=10, bold=False, color=None):
        if not s:
            return
        font = "/F2" if bold else "/F1"
        c = color or (0, 0, 0)
        self.ops.append(f"{c[0]:.3f} {c[1]:.3f} {c[2]:.3f} rg")
        safe = _pdf_escape(_pdf_encode_text(s))
        self.ops.append("BT")
        self.ops.append(f"{font} {size:.2f} Tf")
        self.ops.append(f"{x:.2f} {y:.2f} Td")
        self.ops.append(f"({safe}) Tj")
        self.ops.append("ET")

    def text_right(self, right_x, y, s, size=10, bold=False, color=None):
        w = _pdf_text_width(s, size, bold)
        self.text(right_x - w, y, s, size=size, bold=bold, color=color)

    def draw_image(self, x, y, w, h, image_index):
        self.ops.append("q")
        self.ops.append(f"{w:.2f} 0 0 {h:.2f} {x:.2f} {y:.2f} cm")
        self.ops.append(f"/Im{image_index} Do")
        self.ops.append("Q")

    def content_bytes(self):
        return ("\n".join(self.ops)).encode("latin1")


class _PdfDocument:
    def __init__(self):
        self.pages = []
        self._images = []

    def new_page(self, **kwargs):
        p = _PdfPage(**kwargs)
        self.pages.append(p)
        return p

    def add_image(self, width, height, rgb_compressed, alpha_compressed):
        """Registra uma imagem RGB+alfa (já comprimidas com zlib) para uso
        em qualquer página do documento. Devolve o índice a passar para
        page.draw_image(...)."""
        self._images.append(
            {"width": width, "height": height, "rgb": rgb_compressed, "alpha": alpha_compressed}
        )
        return len(self._images) - 1

    def build(self):
        objects = []

        def add(content_bytes):
            objects.append(content_bytes)
            return len(objects)

        font_regular_num = add(
            b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>"
        )
        font_bold_num = add(
            b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>"
        )

        image_obj_nums = []
        for img in self._images:
            alpha_num = add(
                f"<< /Type /XObject /Subtype /Image /Width {img['width']} /Height {img['height']} "
                f"/ColorSpace /DeviceGray /BitsPerComponent 8 /Filter /FlateDecode "
                f"/Length {len(img['alpha'])} >>\nstream\n".encode("latin1")
                + img["alpha"]
                + b"\nendstream"
            )
            rgb_num = add(
                f"<< /Type /XObject /Subtype /Image /Width {img['width']} /Height {img['height']} "
                f"/ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /FlateDecode "
                f"/SMask {alpha_num} 0 R /Length {len(img['rgb'])} >>\nstream\n".encode("latin1")
                + img["rgb"]
                + b"\nendstream"
            )
            image_obj_nums.append(rgb_num)

        content_nums = []
        for p in self.pages:
            content = p.content_bytes()
            cnum = add(
                f"<< /Length {len(content)} >>\nstream\n".encode("latin1")
                + content
                + b"\nendstream"
            )
            content_nums.append(cnum)

        pages_placeholder = add(b"")

        image_resources = "".join(
            f" /Im{j} {image_obj_nums[j]} 0 R" for j in range(len(image_obj_nums))
        )
        page_nums = []
        for i, p in enumerate(self.pages):
            resources = f"/Font << /F1 {font_regular_num} 0 R /F2 {font_bold_num} 0 R >>"
            if image_resources:
                resources += f" /XObject <<{image_resources} >>"
            page_obj = (
                f"<< /Type /Page /Parent {pages_placeholder} 0 R "
                f"/MediaBox [0 0 {p.width:.2f} {p.height:.2f}] "
                f"/Resources << {resources} >> "
                f"/Contents {content_nums[i]} 0 R >>"
            ).encode("latin1")
            page_nums.append(add(page_obj))

        kids = " ".join(f"{n} 0 R" for n in page_nums)
        objects[pages_placeholder - 1] = (
            f"<< /Type /Pages /Kids [{kids}] /Count {len(page_nums)} >>"
        ).encode("latin1")

        catalog_num = add(f"<< /Type /Catalog /Pages {pages_placeholder} 0 R >>".encode("latin1"))

        out = bytearray()
        out += b"%PDF-1.4\n%\xe2\xe3\xcf\xd3\n"
        offsets = [0] * (len(objects) + 1)
        for i, content in enumerate(objects, start=1):
            offsets[i] = len(out)
            out += f"{i} 0 obj\n".encode("latin1")
            out += content
            out += b"\nendobj\n"
        xref_offset = len(out)
        out += f"xref\n0 {len(objects) + 1}\n".encode("latin1")
        out += b"0000000000 65535 f \n"
        for i in range(1, len(objects) + 1):
            out += f"{offsets[i]:010d} 00000 n \n".encode("latin1")
        out += (
            f"trailer\n<< /Size {len(objects) + 1} /Root {catalog_num} 0 R >>\n"
            f"startxref\n{xref_offset}\n%%EOF"
        ).encode("latin1")
        return bytes(out)


_PDF_PAGE_W, _PDF_PAGE_H = 595.28, 841.89
_PDF_MARGIN_L, _PDF_MARGIN_R = 50, 50
_PDF_CONTENT_W = _PDF_PAGE_W - _PDF_MARGIN_L - _PDF_MARGIN_R
_PDF_RIGHT_X = _PDF_PAGE_W - _PDF_MARGIN_R
_PDF_BOTTOM_MARGIN = 60

_PDF_BURGUNDY = (0.435, 0.122, 0.141)
_PDF_GOLD = (0.557, 0.408, 0.157)
_PDF_MUTED = (0.435, 0.384, 0.345)
_PDF_BORDER = (0.875, 0.827, 0.765)


def _pdf_money(cents):
    v = (cents or 0) / 100
    s = f"{abs(v):,.2f}"
    s = s.replace(",", "_").replace(".", ",").replace("_", ".")
    return ("-" if v < 0 else "") + "R$ " + s


def _pdf_date_br(iso_date):
    if not iso_date:
        return "-"
    parts = str(iso_date)[:10].split("-")
    if len(parts) != 3:
        return str(iso_date)
    return f"{parts[2]}/{parts[1]}/{parts[0]}"


def _pdf_event_datetime(date_value, time_value):
    if not date_value:
        return "A combinar"
    out = _pdf_date_br(date_value)
    if time_value:
        out += " às " + str(time_value)
    return out


def _pdf_percent(n):
    n = round((n or 0) * 100) / 100
    s = f"{n:.2f}".rstrip("0").rstrip(".")
    return s.replace(".", ",")


def _pdf_quantity_label(item):
    unit = item.get("unit")
    qty = float(item.get("quantity") or 0)
    if unit == "kg":
        s = f"{qty:.3f}".rstrip("0").rstrip(".")
        return s.replace(".", ",") + " kg"
    s = f"{qty:g}"
    return s.replace(".", ",") + " un."


class _QuoteDocumentPdf:
    def __init__(self, quote, settings):
        self.quote = quote
        self.settings = settings
        self.doc = _PdfDocument()
        self.page = None
        self.y = 0
        self._logo_image_index = None

    def _new_page(self):
        self.page = self.doc.new_page(width=_PDF_PAGE_W, height=_PDF_PAGE_H)
        self.y = _PDF_PAGE_H - 55

    def _ensure_space(self, needed):
        if self.y - needed < _PDF_BOTTOM_MARGIN:
            self._new_page()
            return True
        return False

    def _logo_index(self):
        if self._logo_image_index is None:
            logo = _get_logo_image_data()
            if logo:
                self._logo_image_index = self.doc.add_image(
                    logo["width"], logo["height"], logo["rgb"], logo["alpha"]
                )
            else:
                self._logo_image_index = -1  # sentinela: logo indisponível
        return self._logo_image_index if self._logo_image_index >= 0 else None

    def _header(self, continuation=False):
        p = self.page
        header_top = self.y
        logo_index = self._logo_index() if not continuation else None
        if logo_index is not None:
            logo = _get_logo_image_data()
            draw_h = 40
            draw_w = draw_h * logo["width"] / logo["height"]
            p.draw_image(_PDF_MARGIN_L, header_top - draw_h + 6, draw_w, draw_h, logo_index)
        else:
            p.text(_PDF_MARGIN_L, header_top, "PANIFICADORA DREON", size=15, bold=True, color=_PDF_BURGUNDY)

        kind = "ORÇAMENTO" + (" (CONTINUAÇÃO)" if continuation else "")
        p.text_right(_PDF_RIGHT_X, header_top, kind, size=11, bold=True, color=_PDF_BURGUNDY)
        p.text_right(_PDF_RIGHT_X, header_top - 15, self.quote.get("quoteNumber") or "", size=10, bold=True, color=_PDF_MUTED)
        p.text_right(_PDF_RIGHT_X, header_top - 27, "Emitido em " + _pdf_date_br(now_iso()), size=8, color=_PDF_MUTED)
        self.y = header_top - 35
        p.set_stroke(*_PDF_GOLD)
        p.line(_PDF_MARGIN_L, self.y, _PDF_RIGHT_X, self.y, line_width=1.4)
        self.y -= 22

    def _client_block(self):
        p = self.page
        col2_x = _PDF_MARGIN_L + _PDF_CONTENT_W / 2 + 10
        p.text(_PDF_MARGIN_L, self.y, "CLIENTE", size=7.5, bold=True, color=_PDF_GOLD)
        p.text(col2_x, self.y, "EVENTO / RETIRADA", size=7.5, bold=True, color=_PDF_GOLD)
        self.y -= 14
        p.text(_PDF_MARGIN_L, self.y, self.quote.get("customerName") or "Nome do cliente", size=11, bold=True)
        event_date = self.quote.get("eventDate")
        event_time = self.quote.get("eventTime")
        p.text(col2_x, self.y, _pdf_event_datetime(event_date, event_time), size=11, bold=True)
        self.y -= 13
        p.text(_PDF_MARGIN_L, self.y, self.quote.get("customerPhone") or "Telefone não informado", size=9, color=_PDF_MUTED)
        p.text(col2_x, self.y, "Válido até " + _pdf_date_br(self.quote.get("validUntil")), size=9, color=_PDF_MUTED)
        self.y -= 18
        p.set_stroke(*_PDF_BORDER)
        p.line(_PDF_MARGIN_L, self.y, _PDF_RIGHT_X, self.y, line_width=0.8)
        self.y -= 18

    def _items_table_header(self):
        p = self.page
        p.text(_PDF_MARGIN_L, self.y, "ITEM", size=7.5, bold=True, color=_PDF_MUTED)
        p.text(_PDF_MARGIN_L + 300, self.y, "QTD.", size=7.5, bold=True, color=_PDF_MUTED)
        p.text_right(_PDF_RIGHT_X, self.y, "VALOR", size=7.5, bold=True, color=_PDF_MUTED)
        self.y -= 8
        p.set_stroke(*_PDF_BORDER)
        p.line(_PDF_MARGIN_L, self.y, _PDF_RIGHT_X, self.y, line_width=0.8)
        self.y -= 14

    def _items(self):
        items = self.quote.get("items") or []
        if not items:
            self.page.text(_PDF_MARGIN_L, self.y, "Nenhum item.", size=10, color=_PDF_MUTED)
            self.y -= 16
            return
        self._items_table_header()
        for item in items:
            if self._ensure_space(20):
                self._header(continuation=True)
                self._items_table_header()
            p = self.page
            name = item.get("productName") or ""
            lines = _pdf_wrap_text(name, 9.5, 290) or [""]
            qty_label = _pdf_quantity_label(item)
            value = _pdf_money(item.get("totalCents"))
            p.text(_PDF_MARGIN_L, self.y, lines[0], size=9.5)
            p.text(_PDF_MARGIN_L + 300, self.y, qty_label, size=9.5)
            p.text_right(_PDF_RIGHT_X, self.y, value, size=9.5, bold=True)
            self.y -= 13
            for extra in lines[1:]:
                if self._ensure_space(13):
                    self._header(continuation=True)
                    self._items_table_header()
                self.page.text(_PDF_MARGIN_L, self.y, extra, size=9.5)
                self.y -= 13
            self.y -= 3
        self.y -= 6
        self.page.set_stroke(*_PDF_GOLD)
        self.page.line(_PDF_MARGIN_L, self.y, _PDF_RIGHT_X, self.y, line_width=1.2)
        self.y -= 20

    def _totals(self):
        q = self.quote
        subtotal = q.get("subtotalCents") or 0
        final_cents = q.get("finalCents")
        if final_cents is None:
            final_cents = subtotal
        discount_cents = subtotal - final_cents
        discount_percent = q.get("discountPercent") or 0
        deposit_paid = q.get("depositPaidCents")
        has_deposit = deposit_paid is not None

        rows = [("Valor total", _pdf_money(subtotal), False)]
        if discount_cents != 0:
            label = f"Desconto ({_pdf_percent(discount_percent)}%)" if discount_cents > 0 else "Acréscimo"
            sign = "-" if discount_cents > 0 else "+"
            rows.append((label, sign + _pdf_money(abs(discount_cents)), False))
            rows.append(("Valor final", _pdf_money(final_cents), True))
        if has_deposit:
            rows.append(("Sinal já recebido", _pdf_money(deposit_paid), False))
            residual = final_cents - deposit_paid
            rows.append(("Valor restante a receber", _pdf_money(residual), True))
        else:
            deposit_percent = float(self.settings.get("deposit_percent") or 50)
            suggested = round(final_cents * deposit_percent / 100)
            rows.append((f"Sinal sugerido de {deposit_percent:g}%", _pdf_money(suggested), False))

        self._ensure_space(18 * len(rows) + 10)
        p = self.page
        box_w = 260
        box_x = _PDF_RIGHT_X - box_w
        p.set_stroke(*_PDF_GOLD)
        p.line(box_x, self.y, _PDF_RIGHT_X, self.y, line_width=1.2)
        self.y -= 16
        for label, value, strong in rows:
            size = 11 if strong else 9.5
            p.text(box_x, self.y, label, size=size, bold=strong)
            p.text_right(_PDF_RIGHT_X, self.y, value, size=size, bold=True, color=_PDF_BURGUNDY if strong else None)
            self.y -= 16
        self.y -= 6

    def _notes(self):
        notes = (self.quote.get("notes") or "").strip()
        if not notes:
            return
        lines = _pdf_wrap_text(notes, 9, _PDF_CONTENT_W - 20)
        needed = 16 + 13 * len(lines) + 14
        self._ensure_space(needed)
        p = self.page
        box_top = self.y
        p.text(_PDF_MARGIN_L + 10, self.y, "OBSERVAÇÕES", size=7.5, bold=True, color=_PDF_GOLD)
        self.y -= 14
        for line in lines:
            p.text(_PDF_MARGIN_L + 10, self.y, line, size=9)
            self.y -= 13
        box_bottom = self.y - 4
        p.set_stroke(*_PDF_BORDER)
        p.rect(_PDF_MARGIN_L, box_bottom, _PDF_CONTENT_W, box_top - box_bottom + 16, stroke=True, line_width=0.8)
        self.y -= 14

    def _payment_box(self):
        settings = self.settings
        note = (settings.get("payment_note") or "").strip()
        lead = settings.get("lead_time_days") or "2"
        lead_line = f"Pedidos para eventos devem ser feitos com no mínimo {lead} dias de antecedência."
        note_lines = _pdf_wrap_text(note, 9.5, _PDF_CONTENT_W - 24) if note else []
        lead_lines = _pdf_wrap_text(lead_line, 8, _PDF_CONTENT_W - 24)
        total_lines = 1 + len(note_lines) + len(lead_lines)
        box_h = 14 + total_lines * 13 + 10
        self._ensure_space(box_h + 10)
        p = self.page
        top = self.y
        p.set_fill(*_PDF_BURGUNDY)
        p.rect(_PDF_MARGIN_L, top - box_h, _PDF_CONTENT_W, box_h, fill=True)
        ty = top - 16
        p.text(_PDF_MARGIN_L + 12, ty, "Confirmação da encomenda", size=10, bold=True, color=(1, 1, 1))
        ty -= 14
        for line in note_lines:
            p.text(_PDF_MARGIN_L + 12, ty, line, size=9.5, color=(0.96, 0.96, 0.96))
            ty -= 13
        for line in lead_lines:
            p.text(_PDF_MARGIN_L + 12, ty, line, size=8, color=(0.88, 0.85, 0.85))
            ty -= 11
        self.y = top - box_h - 16

    def _footer(self):
        s = self.settings
        self._ensure_space(40)
        p = self.page
        p.set_stroke(*_PDF_BORDER)
        p.line(_PDF_MARGIN_L, self.y, _PDF_RIGHT_X, self.y, line_width=0.8)
        self.y -= 14
        p.text(_PDF_MARGIN_L, self.y, f"{s.get('company_name','')} · CNPJ {s.get('cnpj','')}", size=8, bold=True, color=_PDF_MUTED)
        self.y -= 11
        p.text(_PDF_MARGIN_L, self.y, s.get("address", ""), size=8, color=_PDF_MUTED)
        self.y -= 11
        p.text(_PDF_MARGIN_L, self.y, f"{s.get('phone','')} · {s.get('email','')}", size=8, color=_PDF_MUTED)
        self.y -= 11

    def build(self):
        self._new_page()
        self._header()
        self._client_block()
        self._items()
        self._totals()
        self._notes()
        self._payment_box()
        self._footer()
        return self.doc.build()


def build_quote_pdf(quote, settings):
    return _QuoteDocumentPdf(quote, settings).build()


def build_pdf_filename(quote):
    number = (quote.get("quoteNumber") or "orcamento").strip()
    name = (quote.get("customerName") or "").strip()
    base = number + (" - " + name if name else "")
    base = re.sub(r'[\\/:*?"<>|]', "", base)  # remove caracteres inválidos em nome de arquivo
    base = " ".join(base.split())
    return (base or "orcamento") + ".pdf"


